    ///
    /// - Parameters:
    ///   - task: Task ID (`tsk_...`).
    ///   - team: Explicit owning team for privileged calls.
    ///   - user: Explicit owning user for privileged calls.
    ///   - agent: Explicit owning agent for privileged calls.
    ///   - org: Explicit organization for privileged calls; must agree with owner.
    ///   - limit: Maximum links to return. Capped at 100.
    ///   - afterCursor: Opaque cursor returned by the previous page.
    /// - Returns: Successful response
    public func list(task: String, team: String? = nil, user: String? = nil, agent: String? = nil, org: String? = nil, limit: Int? = nil, afterCursor: String? = nil) async throws -> TaskLinkListResponse {
        var query: [(String, String)] = []
