            query.append(("team", team))
        }
        if let user = user {
            query.append(("user", user))
        }
        if let agent = agent {
            query.append(("agent", agent))
        }
        if let org = org {
            query.append(("org", org))
        }
        if let limit = limit {
            query.append(("limit", String(limit)))
        }
        if let afterCursor = afterCursor {
            query.append(("after_cursor", afterCursor))
        }
        return try await http.request("/api/v1/tasks/\(task)/links", query: query)
    }

    /// Add an external link to a task
    ///
    /// Adds an indexed identity without changing the referenced object's ownership or ACL.
    /// For private files, upload with POST /api/v1/files, then pass external_scope=platform,
    /// object_type=file and object_id=fil_.... The reserved platform namespace means the
    /// authenticated current backend/app/sandbox, not a hostname or stored URL.
    /// File attachment requires both task mutation permission and current file read access.
    /// List and reverse lookup omit files that are missing or no longer readable, including
    /// thread-restricted files. The one exception is the task's live lease holder in the
    /// task's organization: the list shows it every linked file it may read through the task
    /// (GET /api/v1/files/:file?task=tsk_...). Generic identities are not resolved as local files.
    /// GET /api/v1/files/:file rechecks permission and returns a fresh expiring download URL;
    /// never persist that URL as the link identity. Existing signed URLs remain usable until
    /// their expiry. Task activity and replay may retain opaque file IDs, not file metadata,
    /// and confer no file access.
    /// Retain the upload response's file ID if attachment fails and retry the link request.
    /// Detaching or deleting a task does not delete the file. Deleting a file leaves historical
    /// link events intact; replay does not restore bytes or access. No ACL grant is implicit.
    /// Agent-owned uploads use an authorized human session; agent-only file credentials
    /// remain unsupported.
    /// Download URLs depend on the configured storage provider. The development local
    /// provider returns a local URL prefix plus a storage path, but Platform does not
    /// serve that path over HTTP. Local-provider verification reads bytes from the
    /// running Platform's configured storage directory after authorized metadata reads;
    /// it does not prove HTTP download authorization. Serving local downloads through
    /// an authorization-preserving route is a separate follow-up, not a public /storage
    /// mount. Served providers are verified through their HTTP download URLs.
    ///
    /// - Parameters:
    ///   - task: Task ID (`tsk_...`).
    ///   - input: Request body.
    /// - Returns: The created external link, with its identity normalized.
    public func create(task: String, input: TaskLinkCreateInput) async throws -> TaskExternalLink {
        return try await http.request("/api/v1/tasks/\(task)/links", method: "POST", body: input)
    }
}

public final class TaskResource: Sendable {
    private let http: HttpClient
    public let blockers: BlockerResource
    public let comments: TaskCommentResource
    public let lease: LeaseResource
    public let links: TaskLinkResource

    public init(http: HttpClient) {
        self.http = http
        self.blockers = BlockerResource(http: http)
        self.comments = TaskCommentResource(http: http)
        self.lease = LeaseResource(http: http)
        self.links = TaskLinkResource(http: http)
    }

    /// Delete a task
    ///
    /// Deletes a task from task lists and detail views. The task event stream is
    /// retained for auditability, while comments are removed and direct subtasks
    /// are promoted to top-level tasks.
    /// The delete event is accepted before the read model is updated. Clients
    /// should remove the task from local collections immediately; subsequent reads
    /// converge once the projection processes the event.
    /// Authenticated users may delete tasks they can access using their session
    /// identity. App-scoped developer and server-to-server callers must explicitly
    /// supply the task's `org` and owner. `team` or `user` identifies that owner;
    /// when neither is present, `agent` identifies an agent-owned task. With a team
    /// or user owner, `agent` identifies the acting principal. Each reference is
    /// validated before deletion.
    ///
    /// - Parameters:
    ///   - task: Task ID (`tsk_...`).
    /// - Returns: Empty response. HTTP 204 is returned after the delete event is accepted.
    public func delete(task: String) async throws {
        try await http.requestVoid("/api/v1/tasks/\(task)", method: "DELETE")
    }

    /// Retrieve a task
    ///
    /// Returns the full task object for the specified task ID. Authenticated users
    /// and agents resolve access through their session. App-scoped developer and
    /// server-to-server callers explicitly provide the owning `team`, `user`, or `agent` and
    /// `org`. Callers without access receive a 404.
    ///
    /// - Parameters:
    ///   - task: Task ID (`tsk_...`).
    ///   - team: Explicit owning team (`tem_...`) for privileged calls.
    ///   - user: Explicit owning user (`usr_...`) for privileged calls.
    ///   - agent: Explicit owning agent (`agi_...`) for privileged calls.
    ///   - org: Explicit organization (`org_...`) for privileged calls; pass null when unscoped.
    /// - Returns: The requested task.
