            query.append(("team", team))
        }
        if let user = user {
            query.append(("user", user))
        }
        if let agent = agent {
            query.append(("agent", agent))
        }
        if let org = org {
            query.append(("org", org))
        }
        return try await http.request("/api/v1/tasks/\(task)", query: query)
    }

