    }

    /// List a task's subtasks
    ///
    /// Returns a bounded page of the specified task's subtasks (tasks whose
    /// `parent` is this task), newest first. Subtasks nest exactly one level, so
    /// entries never have subtasks of their own. Privileged callers explicitly
    /// provide the owning `team`, `user`, or `agent` and `org`.
    ///
    /// - Parameters:
    ///   - task: Parent task ID (`tsk_...`).
    ///   - team: Explicit owning team (`tem_...`) for privileged calls.
    ///   - user: Explicit owning user (`usr_...`) for privileged calls.
    ///   - agent: Explicit owning agent (`agi_...`) for privileged calls.
    ///   - org: Explicit organization (`org_...`) for privileged calls; pass null when unscoped.
    ///   - limit: Maximum subtasks to return. Capped at 100.
    ///   - afterCursor: Opaque cursor returned by the previous page.
    /// - Returns: Successful response
    public func subtasks(task: String, team: String? = nil, user: String? = nil, agent: String? = nil, org: String? = nil, limit: Int? = nil, afterCursor: String? = nil) async throws -> TaskSubtasksResponse {
        var query: [(String, String)] = []
        if let team = team {
            query.append(("team", team))
        }
        if let user = user {
            query.append(("user", user))
        }
        if let agent = agent {
            query.append(("agent", agent))
        }
        if let org = org {
            query.append(("org", org))
        }
        if let limit = limit {
            query.append(("limit", String(limit)))
        }
        if let afterCursor = afterCursor {
            query.append(("after_cursor", afterCursor))
        }
        return try await http.request("/api/v1/tasks/\(task)/subtasks", query: query)
    }

    /// Transfer one task to a different owner
    ///
    /// Changes one task s privacy owner at the supplied aggregate version. Assignment, creator, source identity, comments, and relationship IDs remain unchanged. Source and destination must have the same app and sandbox; the authenticated user must have authority over both scopes.
    ///
    /// - Parameters:
    ///   - task: Task (`tsk_...`).
    ///   - input: Request body.
    /// - Returns: The task with its new owner.
    public func transferOwnership(task: String, input: TaskTransferOwnershipInput) async throws -> Task2 {
        return try await http.request("/api/v1/tasks/\(task)/transfer_ownership", method: "POST", body: input)
    }
}
